// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Receiver r;

    function setUp() public {
        c = new MyContract();
        r = new Receiver();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.deal(address(this), amount);
        vm.deal(address(c), amount);
        address receiver = address(r);
        uint256 beforeBal = receiver.balance;
        vm.prank(address(this));
        c.sendTo(receiver, amount);
        assertEq(receiver.balance - beforeBal, amount);
    }
}

contract Receiver {
    receive() external payable {}
}
